const seedDB = async () => {
  try {
    await mongoose.connect(process.env.MONGODB_URI);
    console.log('Connected to MongoDB');
    console.log('Seeding football legends...\n');

    let inserted = 0;
    let skipped = 0;

    for (const playerData of legends) {
      const existing = await Player.findOne({ name: playerData.name });
      if (existing) {
        skipped++;
        continue;
      }
      await Player.create(playerData);
      inserted++;
      if (inserted % 50 === 0) {
        console.log(`Progress: ${inserted} players inserted...`);
      }
    }

    console.log(`\nInserted: ${inserted} players`);
    console.log(`Skipped duplicates: ${skipped}`);
    console.log('Database ready.\n');

    await mongoose.connection.close();
    console.log('Done. Database connection closed.');
    process.exit(0);
  } catch (error) {
    console.error('Seeding error:', error);
    process.exit(1);
  }
};

seedDB();
